-- Alapon: ten more Editorial posts (ancient Bengal, history, culture, Durga Puja, Kali Puja).
-- Run in the Supabase SQL editor. Requires migrations 0001-0004. Safe to re-run
-- (posts whose title already exists are skipped).
-- Every post ends with a "সূত্র" (source) line. Written from published sources; a subject
-- expert should review them before wider promotion.

do $seed$
declare
  editorial_id uuid;
begin
  select id into editorial_id from auth.users where email = 'editorial@alapon.invalid';

  if editorial_id is null then
    editorial_id := gen_random_uuid();
    insert into auth.users (
      id, instance_id, aud, role, email, encrypted_password, email_confirmed_at,
      confirmation_token, recovery_token, email_change, email_change_token_new,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at
    ) values (
      editorial_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated',
      'editorial@alapon.invalid', '', now(),
      '', '', '', '',
      '{"provider":"email","providers":["email"]}', '{"name":"Alapon Editorial"}', now(), now()
    );
  end if;

  update public.profiles
     set username = 'alapon_editorial',
         display_name = 'আলাপন সম্পাদকীয়',
         privacy_level = 'public',
         is_adult = true
   where id = editorial_id;

  -- Timestamps are staggered (1-10 hours ago) so these become the newest editorials and the
  -- 5-posts-per-hour limit does not apply.
  insert into public.posts (author_id, category_slug, title, body, status, moderation_status, created_at)
  select editorial_id, 'editorial', v.title, v.body, 'published', 'approved',
         now() - (v.hours_ago * interval '1 hour')
  from (values
    ($b$কলকাতার কোনো প্রতিষ্ঠাতা নেই - আদালতের রায়ে$b$, $b$বহুদিন জব চার্নককে কলকাতার প্রতিষ্ঠাতা বলা হতো, ১৬৯০ সালকে ধরা হতো শহরের জন্মবর্ষ। কিন্তু ২০০৩ সালে কলকাতা হাইকোর্ট রায় দেয়, কলকাতার কোনো একক প্রতিষ্ঠাতা নেই - সুতানুটি, কলিকাতা ও গোবিন্দপুর, এই তিন গ্রামের পুরোনো বসতি থেকে শহরটি ধীরে ধীরে গড়ে উঠেছে। ১৬৯৮ সালে ইংরেজ কোম্পানি এই তিন গ্রামের স্বত্ব কেনে সাবর্ণ রায়চৌধুরী পরিবারের কাছ থেকে। সূত্র: কলকাতা হাইকোর্ট, ২০০৩-এর রায়।$b$, 1),
    ($b$সন্ধিপুজো: অষ্টমী-নবমীর সেই বিশেষ ৪৮ মিনিট$b$, $b$অষ্টমী তিথির শেষ ২৪ মিনিট আর নবমী তিথির প্রথম ২৪ মিনিট, এই মোট ৪৮ মিনিটের সন্ধিক্ষণে হয় সন্ধিপুজো। প্রচলিত বিধানে তখন ১০৮টি প্রদীপ জ্বালিয়ে ও ১০৮টি পদ্ম দিয়ে দেবীর আরাধনা করা হয়। বিশ্বাস, এই সন্ধিক্ষণেই দেবী চামুণ্ডারূপে চণ্ড ও মুণ্ড অসুরকে বধ করেছিলেন। তাই পঞ্জিকায় সন্ধিক্ষণের সময় নিয়ে এত আগ্রহ। সূত্র: দেবীমাহাত্ম্য (চণ্ডী); প্রচলিত পঞ্জিকা ও পুজোবিধি।$b$, 2),
    ($b$আমরা যে কালীকে চিনি, তার প্রচারক নবদ্বীপের এক তান্ত্রিক$b$, $b$ষোড়শ-সপ্তদশ শতকের নবদ্বীপের তন্ত্রসাধক কৃষ্ণানন্দ আগমবাগীশকে আজকের পরিচিত দক্ষিণাকালী রূপের প্রচারক বলে মানা হয়। তাঁর সংকলিত 'বৃহৎ তন্ত্রসার' গ্রন্থে কালীর ধ্যানমন্ত্র ও পুজোবিধি আছে। প্রচলিত কথা, স্বপ্নে পাওয়া রূপ থেকেই তিনি প্রথম প্রতিমা গড়ান। দীপাবলির অমাবস্যায় বাংলায় শ্যামাপুজোর প্রচলনে এই ধারার বড় ভূমিকা মানা হয়। সূত্র: বৃহৎ তন্ত্রসার; বাংলার তন্ত্রচর্চার ইতিহাস।$b$, 3),
    ($b$চন্দ্রকেতুগড়: মাটির নিচে ঘুমিয়ে থাকা দুই হাজার বছরের নগর$b$, $b$উত্তর ২৪ পরগনার বেড়াচাঁপার কাছে চন্দ্রকেতুগড়ের ঢিবি খুঁড়ে মিলেছে এক প্রাচীন নগরের ধ্বংসাবশেষ। আনুমানিক খ্রিস্টপূর্ব তৃতীয় শতক থেকে গুপ্তযুগ পর্যন্ত এখানে বসতি ছিল। সবচেয়ে বিখ্যাত আবিষ্কার সূক্ষ্ম কারুকাজের পোড়ামাটির ফলক, যার অনেকগুলি কলকাতার আশুতোষ মিউজিয়ামে সংরক্ষিত। সূত্র: ভারতীয় পুরাতত্ত্ব সর্বেক্ষণের খনন-প্রতিবেদন; আশুতোষ মিউজিয়াম।$b$, 4),
    ($b$তাম্রলিপ্ত: চিনা পরিব্রাজকদের চোখে বাংলার সমুদ্রবন্দর$b$, $b$আজকের তমলুকই প্রাচীন তাম্রলিপ্ত, গঙ্গার মোহনার কাছে বাংলার প্রধান সমুদ্রবন্দর। পঞ্চম শতকের গোড়ায় চিনা পরিব্রাজক ফা-হিয়েন এখান থেকে জাহাজে সিংহলের পথে রওনা দেন, আর সপ্তম শতকে জুয়ান জাং এই বন্দরনগরের সমৃদ্ধির কথা লিখে যান। এই বন্দর দিয়েই ভারতের সঙ্গে দক্ষিণ-পূর্ব এশিয়া ও চিনের সমুদ্রবাণিজ্য চলত। সূত্র: ফা-হিয়েন ও জুয়ান জাং-এর ভ্রমণবিবরণ।$b$, 5),
    ($b$শশাঙ্ক: গৌড়ের প্রথম শক্তিশালী স্বাধীন রাজা$b$, $b$সপ্তম শতকের গোড়ায় গৌড়ের রাজা শশাঙ্ককে বাংলার প্রথম পরিচিত শক্তিশালী স্বাধীন শাসক ধরা হয়। তাঁর রাজধানী ছিল কর্ণসুবর্ণ, আজকের মুর্শিদাবাদ জেলার রাঙামাটি অঞ্চলে। উত্তর ভারতের রাজনীতিতেও তাঁর প্রভাব ছিল, যার উল্লেখ আছে বাণভট্টের 'হর্ষচরিত' ও জুয়ান জাং-এর লেখায়। সূত্র: হর্ষচরিত; জুয়ান জাং-এর বিবরণ।$b$, 6),
    ($b$বিষ্ণুপুরের পোড়ামাটির মন্দির: ইটের গায়ে রামায়ণ-মহাভারত$b$, $b$বাঁকুড়ার বিষ্ণুপুর ছিল মল্ল রাজাদের রাজধানী। সপ্তদশ-অষ্টাদশ শতকে তাঁদের তৈরি শ্যামরায় (১৬৪৩), জোড়বাংলা, রাসমঞ্চ প্রভৃতি মন্দিরের দেয়াল ঢাকা পোড়ামাটির ফলকে - রামায়ণ, মহাভারত, কৃষ্ণলীলা আর সেকালের জীবনের ছবি। এই মন্দিরগুলি ইউনেস্কোর বিশ্ব ঐতিহ্যের সম্ভাব্য তালিকায় আছে। সূত্র: ভারতীয় পুরাতত্ত্ব সর্বেক্ষণ; UNESCO Tentative List।$b$, 7),
    ($b$পুরুলিয়ার ছৌ: মুখোশ পরা নাচ, যার স্বীকৃতি দিয়েছে ইউনেস্কো$b$, $b$ছৌ নাচে নর্তকেরা মুখোশ পরে রামায়ণ, মহাভারত ও পুরাণের কাহিনি ফুটিয়ে তোলেন - সংলাপ ছাড়াই, শুধু শরীরের ছন্দে আর ঢোল, ধামসা, সানাইয়ের সুরে। পুরুলিয়ার চড়িদা গ্রাম মুখোশ বানানোর জন্য বিখ্যাত। ২০১০ সালে ইউনেস্কো ভারতের 'ছৌ নৃত্য'-কে অস্পর্শনীয় সাংস্কৃতিক ঐতিহ্যের তালিকায় স্থান দেয়; পুরুলিয়া তার তিন ধারার একটি। সূত্র: UNESCO, ২০১০।$b$, 8),
    ($b$প্রতিমার মাটি: কেন লাগে 'নিষিদ্ধ পল্লির' দোরগোড়ার মাটি?$b$, $b$প্রতিমা গড়ার আগে কুমোরটুলির শিল্পীরা গঙ্গার পলিমাটির সঙ্গে মেশান পুণ্যমাটি - যার একটি উপাদান নিষিদ্ধ পল্লির দোরগোড়ার মাটি। প্রচলিত ব্যাখ্যা: সমাজ যাঁদের দূরে সরিয়ে রাখে, তাঁদের ছাড়া দেবীর আরাধনা সম্পূর্ণ হয় না; আবার কেউ বলেন, ওই দোরগোড়ায় মানুষ নিজের পুণ্য রেখে ভেতরে ঢোকে, তাই মাটি পবিত্র। সূত্র: কুমোরটুলির শিল্পীদের প্রচলিত বিবরণ।$b$, 9),
    ($b$কলকাতার চিনা কালীবাড়িতে প্রসাদ নুডলস!$b$, $b$কলকাতার ট্যাংরায় চিনা বসতির মাঝে আছে এক কালীমন্দির, যেখানে ভক্তদের বড় অংশই চিনা সম্প্রদায়ের মানুষ। প্রচলিত বিবরণ অনুযায়ী প্রায় ষাট বছর আগে এক গাছের নিচে রাখা পাথরকে কালীরূপে পুজো শুরু হয়। এখানে প্রসাদ হিসেবে মেলে নুডলস, চপ সুই আর ভাত। বাংলার মিশ্র সংস্কৃতির এক অনন্য উদাহরণ। সূত্র: সংবাদ ও ভ্রমণ-প্রতিবেদন।$b$, 10)
  ) as v(title, body, hours_ago)
  where not exists (select 1 from public.posts p where p.title = v.title);
end
$seed$;

-- Check: how many editorial posts exist now.
select count(*) as editorial_posts from public.posts where category_slug = 'editorial';
